        self.cookie_store_name = cookie_store_name
        self.cookie_store = Set()  # or pass dict directly

    def validate(self, cookie_hash, from_name, to_name):
        try:
            if not self.cookie_store.hashes(cookie_hash):
                raise ValueError(f"Invalid cookie: {from_name} exists")
            if self.cookie_store.hashes(from_name):
                raise ValueError(f"Invalid cookie: {to_name} exists")
            return True
        except (InvalidCookie, KeyError, IndexError):
            raise ValueError(f"Invalid cookie: {from_name} or {to_name}")
            return False

    def set_from(self, from_name, to_name):
        self.cookie_store.update(self.cookie_store.get(from_name), self.cookie_store.get(to_name))

    def set_to(self, from_name, to_name):
        self.cookie_store.update(self.cookie_store.get(from_name), self.cookie_store.get(to_name))
